import {MIN,MAX,clamp,preset} from './math.mjs';
export const STORAGE_KEY='harmonic-lens.settings.v2';
const types=['sine','uniform','inverse','inverse2','triangle','square','custom'];
export function defaults(){return {tones:[200,250].map(f=>({f,amps:preset('inverse',16),count:16,preset:'inverse',phase:'inverse',db:-24,playing:false,selected:-1,snap:false})),panelHeight:800,panelHeightAuto:true,harmonicSnap:false,linkLevels:false,mode:'reference',routing:'mixed',axisLabels:'frequency',axisScale:'log',ratioMode:'fraction',ratioSnap:false,fixRatio:false,lockedRatio:1.25,ratioParts:[5,4],view:{lo:Math.log2(50),hi:Math.log2(8000)},guide:false}}
const finite=(n,f)=>typeof n==='number'&&Number.isFinite(n)?n:f;
export function sanitize(raw){const d=defaults();if(!raw||typeof raw!=='object')return d;for(const k of ['mode','routing','axisLabels','axisScale','ratioMode']){const allowed={mode:['reference','rms'],routing:['mixed','split'],axisLabels:['frequency','notes','both'],axisScale:['log','linear'],ratioMode:['fraction','slider','cents']}[k];if(allowed.includes(raw[k]))d[k]=raw[k]}
for(const k of ['ratioSnap','fixRatio','guide','linkLevels','harmonicSnap'])d[k]=raw[k]===true;
if(Array.isArray(raw.tones)&&raw.tones.length===2)d.tones=d.tones.map((s,i)=>{const t=raw.tones[i];if(!t||typeof t!=='object')return s;const count=clamp(Math.round(finite(t.count,16)),1,32);return {...s,f:clamp(finite(t.f,s.f),MIN,MAX),db:clamp(finite(t.db,-24),-60,-1),count,preset:types.includes(t.preset)?t.preset:'inverse',phase:['saw','sine','uniform','inverse','inverse2','triangle','square'].includes(t.phase)?t.phase:'inverse',snap:t.snap===true,selected:clamp(Math.round(finite(t.selected,-1)),-1,count-1),amps:Array.from({length:count},(_,n)=>clamp(finite(t.amps?.[n],preset('inverse',count)[n]),0,2))}});
if(d.linkLevels)d.tones[1].db=d.tones[0].db;
const r=d.tones[0].f>0&&d.tones[1].f>0?d.tones[1].f/d.tones[0].f:NaN;d.lockedRatio=Number.isFinite(r)&&r>0?r:finite(raw.lockedRatio,1.25);if(d.lockedRatio<=0)d.lockedRatio=1.25;if(Array.isArray(raw.ratioParts)&&raw.ratioParts.length===2&&raw.ratioParts.every(n=>typeof n==='number'&&Number.isFinite(n)&&n>0)&&Math.abs(Math.log2(raw.ratioParts[0]/raw.ratioParts[1]/r))<1e-8)d.ratioParts=[...raw.ratioParts];else d.ratioParts=Number.isFinite(r)?[r,1]:[5,4];
d.panelHeightAuto=typeof raw.panelHeightAuto==='boolean'?raw.panelHeightAuto:!Number.isFinite(raw.panelHeight);
d.panelHeight=clamp(Math.round(finite(raw.panelHeight,800)),420,1600);
const low=d.axisScale==='log'?Math.log2(.01):0,high=d.axisScale==='log'?Math.log2(48000):48000;
if(raw.view&&Number.isFinite(raw.view.lo)&&Number.isFinite(raw.view.hi)&&raw.view.lo>=low&&raw.view.hi<=high&&raw.view.hi-raw.view.lo>=(d.axisScale==='log'?.06:1))d.view={lo:raw.view.lo,hi:raw.view.hi};else if(d.axisScale==='linear')d.view={lo:50,hi:8000};return d}
export function linkedFrequencies(a,b,index,requested,ratio){if(!ratio)return index===0?[clamp(requested,MIN,MAX),b]:[a,clamp(requested,MIN,MAX)];if(index===0){a=clamp(requested,Math.max(MIN,MIN/ratio),Math.min(MAX,MAX/ratio));return [a,a*ratio]}b=clamp(requested,Math.max(MIN,MIN*ratio),Math.min(MAX,MAX*ratio));return [b/ratio,b]}
